import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"石鼓歌","description":"","frontmatter":{"title":"石鼓歌","date":"2026-11-23T00:00:00.000Z","seq":25,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 七言古诗》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"韩愈","source_book":"唐诗三百首"},"headers":[],"relativePath":"blogs/唐诗三百首·七言古诗/石鼓歌.md","filePath":"blogs/唐诗三百首·七言古诗/石鼓歌.md"}'),o={name:"blogs/唐诗三百首·七言古诗/石鼓歌.md"};function l(c,a,n,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="石鼓歌" tabindex="-1">石鼓歌 <a class="header-anchor" href="#石鼓歌" aria-label="Permalink to &quot;石鼓歌&quot;">​</a></h1><p class="poem-meta">唐 · 韩愈　·　七言古诗</p><div class="poem"><p class="poem-stanza">张生手持石鼓文，劝我试作石鼓歌。</p><p class="poem-stanza">少陵无人谪仙死，才薄将奈石鼓何。</p><p class="poem-stanza">周纲凌迟四海沸，宣王愤起挥天戈。</p><p class="poem-stanza">大开明堂受朝贺，诸侯剑佩鸣相磨。</p><p class="poem-stanza">搜于岐阳骋雄俊，万里禽兽皆遮罗。</p><p class="poem-stanza">镌功勒成告万世，凿石作鼓隳嵯峨。</p><p class="poem-stanza">从臣才艺咸第一，拣选撰刻留山阿。</p><p class="poem-stanza">雨淋日灸野火燎，鬼物守护烦㧑呵。</p><p class="poem-stanza">公从何处得纸本，毫发尽备无差讹。</p><p class="poem-stanza">辞严义密读难晓，字体不类隶与蝌。</p><p class="poem-stanza">年深岂免有缺画，快剑斫断生蛟鼍。</p><p class="poem-stanza">鸾翔凤翥众仙下，珊瑚碧树交枝柯。</p><p class="poem-stanza">金绳铁索锁钮壮，古鼎跃水龙腾梭。</p><p class="poem-stanza">陋儒编诗不收入，二雅褊迫无委蛇。</p><p class="poem-stanza">孔子西行不到秦，掎摭星宿遗羲娥。</p><p class="poem-stanza">嗟余好古生苦晚，对此涕泪双滂沱。</p><p class="poem-stanza">忆昔初蒙博士征，其年始改称元和。</p><p class="poem-stanza">故人从军在右辅，为我度量掘臼科。</p><p class="poem-stanza">濯冠沐浴告祭酒，如此至宝存岂多。</p><p class="poem-stanza">毡包席裹可立致，十鼓只载数骆驼。</p><p class="poem-stanza">荐诸太庙比郜鼎，光价岂止百倍过。</p><p class="poem-stanza">圣恩若许留太学，诸生讲解得切磋。</p><p class="poem-stanza">观经鸿都尚填咽，坐见举国来奔波。</p><p class="poem-stanza">剜苔剔藓露节角，安置妥帖平不颇。</p><p class="poem-stanza">大厦深檐与盖覆，经历久远期无佗。</p><p class="poem-stanza">中朝大官老于事，讵肯感激徒媕婀。</p><p class="poem-stanza">牧童敲火牛砺角，谁复著手为摩挲。</p><p class="poem-stanza">日销月铄就埋没，六年西顾空吟哦。</p><p class="poem-stanza">羲之俗书趁姿媚，数纸尚可博白鹅。</p><p class="poem-stanza">继周八代争战罢，无人收拾理则那。</p><p class="poem-stanza">方今太平日无事，柄任儒术崇丘轲。</p><p class="poem-stanza">安能以此尚论列，愿借辩口如悬河。</p><p class="poem-stanza">石鼓之歌止于此，呜呼吾意其蹉跎。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
